    /**
     * 0 to 1: the sender's volume.
     */
    public var volume: Double
    /**
     * Songs of the queue this device's library doesn't have (left out).
     */
    public var unknownSongs: UInt32
    /**
     * HandoffFailed: why, in words for a toast.
     */
