public func hello(name: String) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_encore_core_fn_func_hello(
        FfiConverterString.lower(name),uniffiCallStatus
    )
})
}

